# owner: platform
from rosterkit.models import Student
from rosterkit.errors import ProjectError
from operator import attrgetter


def _check(students):
    if not students:
        raise ProjectError("no students given")
    for item in students:
        if not item.email:
            raise ProjectError(
                f"no email for {item.display_name}")


def _cells(students):
    ordered = sorted(
        students, key=attrgetter("display_name"))
    return [
        (item.display_name, item.section, item.email)
        for item in ordered
    ]


def _line(cell, sizes):
    pairs = zip(cell, sizes)
    padded = [text.ljust(size) for text, size in pairs]
    return "  ".join(padded).rstrip()


# ---
def contact_rows(students: "list[Student]") -> "list[str]":
    _check(students)
    cells = _cells(students)
    sizes = [
        max(map(len, column)) for column in zip(*cells)
    ]
    return [_line(cell, sizes) for cell in cells]

